metric_list.aggregation:
def lev_agg(items):
    goodness = 0
    for item in items:
      dist = levv(item[0], item[1])
      goodness += 1 / (1 + dist)
    return goodness / len(items)

def precise_agg(items):
    goodness = 0
    for item in items:
      if item[0] == item[1]:
        goodness += 1
    return goodness / len(items)

def raw_lev_agg(items):
    total_lev = 0
    for item in items:
      dist = levv(item[0], item[1])
      total_lev += dist
    return total_lev / len(items)

